async function bootstrapGateway(input = {}) {
  await storeManager.initialize();
  if (storeManager.hasInitializationError()) {
    return {
      ok: false,
      code: "storage-unavailable",
      message: storeManager.getInitializationError()?.message ?? "unknown storage error",
      host: "",
      port: 0
    };
  }
  if (storeManager.isCredentialEncryptionDegraded()) {
    input.onWarning?.(
      `No OS keystore here: upstream credentials are stored as plaintext in ${storeManager.getStoragePath()}/data.json. Restrict that directory (chmod 700) or run on a host with a keystore.`
    );
  }
  await primeModelProbeCache();
  configureModelListRefresh(storeManager.getConfig().modelListRefresh);
  scheduler.start();
  void aggregateProviderManager.autoProvisionKeyless();
  await registerIpcHandlers(null);
  const config = storeManager.getConfig();
  const host2 = config.proxyHost || "127.0.0.1";
  const port = config.proxyPort;
  const started = proxyServer.isRunning() || await proxyServer.start(port, host2);
  if (!started) {
    return {
      ok: false,
      code: "listen-failed",
      message: `Could not listen on ${host2}:${port} (in use, or refused: a non-loopback host needs an API key)`,
      host: host2,
      port
    };
  }
  const listening = { host: host2, port, version: getHost().getVersion() };
  input.onListening?.(listening);
  if (!config.managementApi?.enableManagementApi) {
    input.onWarning?.(
      `The management API is off, so no UI can reach this gateway yet. Enable it by setting config.managementApi.enableManagementApi=true plus a managementApiSecret in ${storeManager.getStoragePath()}/data.json, then restart.`
    );
  }
  return { ok: true, listening };
}
function installGatewayShutdownHandlers(onShutdown) {
  let closing = false;
  const shutdown = (signal) => {
    if (closing) return;
    closing = true;
    onShutdown?.(signal);
    shutdownCatalogBatchJobs();
    scheduler.stop();
    void proxyServer.stop().catch(() => void 0).finally(() => {
      storeManager.flushPendingWrites();
      process.exit(0);
    });
  };
  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

